public abstract class CashSuper{
    abstract double acceptCash(double money);
}

public class CashNormal extends CashSuper{
    @override
    double acceptCash(double money) {
        return money;
        // 正常结算直接返回原价
    }
}

public class CashRebate extends CashSuper{
    private double rate = 1.0;

    public CashRebate(double rate){
        //构造方法，传折扣率参数
        this.rate = rate;
    }

    @override
    double acceptCash(double money) {
        return money * rate;
        // 折扣结算
    }
}

public class CashRebate extends CashSuper{
    private double moneyCondition = 300;
    private double mouneyReturn = 100;

    public CashRebate(double moneyCondition,double mouneyReturn){
        //构造方法，传满减参数
        this.moneyCondition = moneyCondition;
        this.mouneyReturn = mouneyReturn;
    }

    @override
    double acceptCash(double money) {
        if (money >= moneyCondition){
            return money - mouneyReturn
        }else{
            return money
        }
    }
}

