// 抽象主题
interface Subject{
    void Request();
}

// 真实主题类
class RealSubject implements Subject{
    public void Request() {
        System.out.println("访问真实主题方法")
    }
}

// 代理类
class Proxy implements Subject{
    private RealSubject realSubject;
    public void Request(){
        if (realSubject == null){
            realSubject = new RealSubject();
        }
        preRequest();//在原本的请求前后增加处理过程
        realSubject.Request();
        postRequest();
    }
    public void preRequest(){System.out.println("访问真实主题前的预处理");}
    public void postRequest(){System.out.println("访问真实主题后的后处理");}
}

// 懒汉式单例
public class LazySingleton{
    private static volatile LazySingleton instance = null;
    // 保证instance在所有线程中同步
    private LazySingleton(){
        //private 避免类在外部被实例化
    }
    public static synchronized LazySingleton getInstance(){
        //getInstance 前加同步
        if(instance == null){
            instance = new LazySingleton();
        }
        return instance;
    }
}


